const DEMO_USERS=[
 {name:"Kavindu Perera",email:"student@smart.lk",password:"student123",role:"student",school:"Royal College",district:"Colombo",stream:"Physical Science",year:"2027"},
 {name:"Ms. Nadeesha Silva",email:"teacher@smart.lk",password:"teacher123",role:"teacher",school:"Smart Learning",district:"Colombo",stream:"",year:""},
 {name:"System Administrator",email:"admin@smart.lk",password:"admin123",role:"admin",school:"Smart Learning",district:"Colombo",stream:"",year:""}
];
function getUsers(){let u=JSON.parse(localStorage.getItem("sl_users")||"null");if(!u){u=DEMO_USERS;localStorage.setItem("sl_users",JSON.stringify(u))}return u}
function setCurrent(user){const safe={...user};delete safe.password;localStorage.setItem("sl_current",JSON.stringify(safe))}
const districtNames=["Ampara","Anuradhapura","Badulla","Batticaloa","Colombo","Galle","Gampaha","Hambantota","Jaffna","Kalutara","Kandy","Kegalle","Kilinochchi","Kurunegala","Mannar","Matale","Matara","Monaragala","Mullaitivu","Nuwara Eliya","Polonnaruwa","Puttalam","Ratnapura","Trincomalee","Vavuniya"];
if(document.getElementById("district")){districtNames.forEach(d=>document.getElementById("district").add(new Option(d,d)));for(let y=2026;y<=2032;y++)document.getElementById("examYear").add(new Option(y,y))}
document.getElementById("loginForm")?.addEventListener("submit",e=>{e.preventDefault();const email=loginEmail.value.trim().toLowerCase(),pass=loginPassword.value;const user=getUsers().find(u=>u.email.toLowerCase()===email&&u.password===pass);if(!user){loginError.textContent="Email or password is incorrect. Try one of the demo accounts.";return}setCurrent(user);location.href=user.role==="admin"?"admin.html":user.role==="teacher"?"teacher.html":"dashboard.html"});
document.getElementById("registerForm")?.addEventListener("submit",e=>{e.preventDefault();registerError.textContent="";if(regPassword.value!==confirmPassword.value){registerError.textContent="Passwords do not match.";return}const users=getUsers();if(users.some(u=>u.email.toLowerCase()===regEmail.value.trim().toLowerCase())){registerError.textContent="An account with this email already exists.";return}const user={name:fullName.value.trim(),email:regEmail.value.trim(),password:regPassword.value,phone:phone.value,school:school.value.trim(),district:district.value,stream:stream.value,year:examYear.value,role:"student"};users.push(user);localStorage.setItem("sl_users",JSON.stringify(users));setCurrent(user);location.href="dashboard.html"});
document.getElementById("forgotPassword")?.addEventListener("click",()=>alert("For this demo, use one of the demo accounts shown below the login form. A production version should connect to a secure password-reset service."));